import pytz
import requests
import json

from datetime import datetime
from collections import ChainMap

from taf.rfrl.procedures.resources.python.scout.decorators import retry_request_on_failure
from taf.rfrl.procedures.resources.python.scout.exceptions import ScoutAPIError, ReportCalculationNotFinished, \
    ReportValidationFailed
from taf.rfrl.procedures.resources.python.logger import log_result, log_operation, log_input_and_output


class ScoutComparator:
    _api_key = "c8174890-43ba-42d8-bb5b-5e8401927045"
    _scout_api_url = "https://scout.nsn-rdnet.net/api/v1/"
    _request_header = {'Content-Type': 'application/vnd.api+json'}

    @log_input_and_output
    def trigger_report_generation(self, scout_tl_name, template_id, reference_start_time, reference_end_time,
                                  current_start_time, current_end_time, first_period_description="previous_run",
                                  second_period_description="present_run", alpha="0.005"):
        """
        Method used to trigger comparator report generation through Scout API interface. Make sure that datetime objects
        contain timezone information as it's required to convert to UTC timezone.
        :param scout_tl_name: name of BTS in Scout Tool, e.g. 10_16_40703-50703_MRBTS-40703
        :type scout_tl_name: str
        :param template_id: id of template that user what to use in Scout Comparator report
        :type template_id: str
        :param reference_start_time: start datetime of old data with timezone
        :type reference_start_time: datetime object
        :param reference_end_time: end datetime of old data with timezone
        :type reference_end_time: datetime object
        :param current_start_time: start datetime of new data with timezone
        :type current_start_time: datetime object
        :param current_end_time: end datetime of new data with timezone
        :type current_end_time: datetime object
        :param first_period_description: first time range description
        :type first_period_description: str
        :param second_period_description: second time range description
        :type second_period_description: str
        :param alpha: the alpha index, used in the t-test calculation, e.g. 0.005
        :type alpha: str
        :return: ID of triggered report
        :rtype: str
        """
        reference_start_time = self._adjust_timestamp(timestamp=reference_start_time)
        reference_end_time = self._adjust_timestamp(timestamp=reference_end_time)
        current_start_time = self._adjust_timestamp(timestamp=current_start_time)
        current_end_time = self._adjust_timestamp(timestamp=current_end_time)

        scout_bts_name = self._get_scout_id(scout_tl_name=scout_tl_name)
        request_payload = self._prepare_payload(template_id=template_id, scout_bts_name=scout_bts_name,
                                                reference_start_time=reference_start_time, reference_end_time=reference_end_time,
                                                first_period_description=first_period_description,
                                                current_start_time=current_start_time, current_end_time=current_end_time,
                                                second_period_description=second_period_description, alpha=alpha)

        log_operation("Triggering Scout report generation...")
        response_data = self._send_request(request_method="POST", endpoint="aggregated_comparator_reports",
                                           data=request_payload)
        report_id = response_data["data"]["attributes"]["comparator_reports"][0]["id"]
        log_result(f"Report with id {report_id} has been successfully triggered!")

        return report_id

    @log_input_and_output
    def validate_report_calculation_successful(self, report_id):
        """
        Validates if calculations for given report ID is finished.
        :param report_id: ID of report user want to check status for
        :type report_id: str
        :return: True if report calculation is finished
        :rtype: bool
        """

        response_data = self._send_request(request_method="GET", endpoint=f"comparator_reports/{report_id}")
        report_status = response_data["data"]["meta"]["status_display"]

        return report_status == "calculation successful"

    def validate_report(self, report_id):
        """
        Validates statuses for each KPI and PM counter compared in report
        :param report_id: ID of report user want to check status for
        :type report_id: str
        :raises ReportCalculationNotFinished: when report calculation didn't finish
        :raises ReportValidationFailed: when Scout report validation failed for checked KPIs and PMs counters
        """
        if not self.validate_report_calculation_successful(report_id=report_id):
            raise ReportCalculationNotFinished("Report calculation is not finished and cannot be validated!")

        response_data = self._send_request(request_method="GET", endpoint=f"comparator_reports/{report_id}")
        self._validate_report_results(response_data)

    @log_input_and_output
    def _extract_measurements_data_from_response(self, response_data, measurement_type):
        measurements = {}
        measurements_data = response_data["data"]["attributes"]["report"]

        for measurement_name, measurement_data in measurements_data[measurement_type].items():
            measurements[measurement_name] = []
            for bts_component, component_data in measurement_data["data"].items():
                measurements[measurement_name].append(
                    {"dist_name": bts_component, "status": component_data["calculations"]["status"]}
                )

        return measurements

    def _validate_report_results(self, response_data):
        kpis_data = self._extract_measurements_data_from_response(
            response_data=response_data, measurement_type="kpis"
        )
        pms_data = self._extract_measurements_data_from_response(
            response_data=response_data, measurement_type="pms"
        )
        measurements_data = self._extract_measurements_data_from_response(
            response_data=response_data, measurement_type="measurements"
        )
        results = dict(ChainMap(kpis_data, pms_data, measurements_data))

        pr_level_statuses = ["failed", "missing before", "missing after"]
        warning_level_statuses = ["error", "partially missing"]
        failed_components = {}
        warning_components = {}

        for measurement_code in results:
            for bts_component in results[measurement_code]:
                if bts_component["status"] == "passed":
                    continue
                elif bts_component["status"] in warning_level_statuses:
                    self._append_elements_to_dict(dictionary=warning_components, key=measurement_code,
                                                  item=bts_component)
                elif bts_component["status"] in pr_level_statuses:
                    self._append_elements_to_dict(dictionary=failed_components, key=measurement_code,
                                                  item=bts_component)

        if warning_components or failed_components:
            raise ReportValidationFailed(
                f"KPIs, PMs and Measurements that need to be check for proper configuration: "
                f"{dict(sorted(warning_components.items()))}\n"
                "------------------------------------------------------------------------------------------------\n"
                f"KPIs, PMs and Measurements that need PR investigation: {dict(sorted(failed_components.items()))}"
            )

        log_result("Report validated successfully!")

    @log_input_and_output
    def _get_scout_id(self, scout_tl_name):
        response_data = self._send_request(request_method="GET", endpoint=f"testlines/{scout_tl_name}")
        return response_data["data"]["id"]

    @log_input_and_output
    def _prepare_payload(self, template_id, scout_bts_name, reference_start_time, reference_end_time, first_period_description,
                         current_start_time, current_end_time, second_period_description, alpha):
        return json.dumps({
            "data": {
                "type": "aggregated_comparator_report",
                "attributes": {
                    "comparator-templates": [{
                        "id": template_id,
                        "type": "comparator_template"
                    }],
                    "testline": {
                        "id": scout_bts_name,
                        "type": "testline"
                    },
                    "reference-start-time": reference_start_time,
                    "reference-end-time": reference_end_time,
                    "first-period-description": first_period_description,
                    "current-start-time": current_start_time,
                    "current-end-time": current_end_time,
                    "second-period-description": second_period_description,
                    "name": f"{datetime.now().strftime('%Y_%m_%d_%H_%M_%S')}_{template_id}_{scout_bts_name}",
                    "alpha": alpha
                }
            }
        })

    @retry_request_on_failure
    def _send_request(self, request_method, endpoint="", **kwargs):
        response = requests.request(method=request_method,
                                    url=f"{self._scout_api_url}{endpoint}/?apitoken={self._api_key}",
                                    headers=self._request_header,
                                    **kwargs)
        self._check_response(response)
        return response.json()

    @staticmethod
    def _check_response(response):
        if not response.ok:
            decoded_content = json.loads(response.content)["errors"][0]
            pointer = decoded_content["source"]["pointer"]
            detail = decoded_content["detail"]
            msg = (
                "Endpoint returned bad response: "
                f"'({response.status_code}) {response.reason} (pointer: {pointer}, detail: {detail})'."
            )
            msg = msg.format(response=response)

            raise ScoutAPIError(msg)

    @staticmethod
    def _append_elements_to_dict(dictionary, key, item):
        try:
            dictionary[key].append(item)
        except KeyError:
            dictionary[key] = [item]

    @staticmethod
    def _adjust_timestamp(timestamp):
        return timestamp.astimezone(pytz.utc).strftime("%Y-%m-%dT%H:%M:00.000Z")
